Expected: FAIL — `undefined: resolveTurnAnchor`.

- [ ] **Step 3: Implement**

Create `turn_anchor.go`:

```go
package agentimport

import (
	"github.com/go-git/go-git/v6"
	"github.com/go-git/go-git/v6/plumbing"
	"github.com/go-git/go-git/v6/plumbing/object"
)

// resolveTurnAnchor picks the commit_sha anchor for one imported turn: the
// LAST candidate (transcript order — the turn's end state) that both resolves
// in the repo and is an ancestor of fallback, else fallback itself. fallback
// is the caller-resolved default-branch tip (Options.LinkCommitSHA); ancestry
// against it doubles as the reachability check, so this function needs no
// branch-name logic. Candidates are short SHAs from transcript gitOperation
// records; squash-merged or rebased-away commits simply fail to resolve or
// fail ancestry and fall through. Empty fallback → "" (unanchorable repo
// imports unlinked, matching resolveImportLinkCommitSHA's contract).
func resolveTurnAnchor(repo *git.Repository, fallback string, candidates []string) string {
	if fallback == "" || len(candidates) == 0 {
		return fallback
	}
	fbCommit, err := repo.CommitObject(plumbing.NewHash(fallback))
	if err != nil {
		return fallback
	}
	for i := len(candidates) - 1; i >= 0; i-- {
		hash, err := repo.ResolveRevision(plumbing.Revision(candidates[i]))
		if err != nil || hash == nil {
			continue
		}
		cand, err := repo.CommitObject(*hash)
		if err != nil {
			continue
		}
		ok, err := cand.IsAncestor(fbCommit)
		if err != nil || !ok {
			continue
		}
		return hash.String()
	}
	return fallback
}

var _ = object.Commit{} // remove if unused after implementation
```

